645	    private List<String> availableKeys() throws Exception {
646	        MvcResult result = mockMvc.perform(get("/api/batches/available"))
647	                .andExpect(status().isOk()).andReturn();
648	        JsonNode array = objectMapper.readTree(result.getResponse().getContentAsString());
649	        List<String> keys = new ArrayList<>();
650	        array.forEach(n -> keys.add(n.path("batchKey").asText()));
651	        return keys;
652	    }
653	
654	    private int callStatus(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder req) {
655	        try {
656	            return mockMvc.perform(req).andReturn().getResponse().getStatus();
657	        } catch (Exception e) {
658	            throw new RuntimeException(e);
659	        }
660	    }
661	
662	    @SafeVarargs
663	    private List<Future<Integer>> runConcurrent(Callable<Integer>... tasks) throws Exception {
664	        ExecutorService pool = Executors.newFixedThreadPool(tasks.length);
665	        CyclicBarrier barrier = new CyclicBarrier(tasks.length);
666	        List<Future<Integer>> futures = new ArrayList<>();
667	        for (Callable<Integer> task : tasks) {
668	            futures.add(pool.submit(() -> {
669	                barrier.await(10, TimeUnit.SECONDS);
670	                return task.call();
671	            }));
672	        }
673	        pool.shutdown();
674	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
675	        return futures;
676	    }
677	}
