425	     * 拆分：仅当前可用的 RELEASED 批次可一次拆成 2～5 个全新子批。
426	     * 子批继承产品编码、生产 UTC 时间与必做检验项，初始 QUARANTINED，
427	     * 不继承检验或批准记录；父批置为 SPLIT 不再可用。
428	     * 创建全部子批、血缘关系与父批状态在同一事务提交；任一子批键已存在或重复，整次 409 且父批不变。
429	     */
430	    public StoredResponse split(String parentKey, SplitRequest req) {
431	        List<SplitRequest.ChildSpec> children = req.children();
432	        List<String> childKeys = children.stream().map(SplitRequest.ChildSpec::batchKey).toList();
433	        if (new HashSet<>(childKeys).size() != childKeys.size()) {
434	            throw ApiException.conflict("子批 batchKey 在请求内重复");
435	        }
436	        List<String> parts = new ArrayList<>();
437	        parts.add("split");
438	        parts.add(parentKey);
439	        for (SplitRequest.ChildSpec child : children) {
440	            parts.add(child.batchKey());
441	            parts.add(child.batchNo());
442	        }
443	        String fingerprint = fingerprint(parts.toArray(new String[0]));
444	        return executeIdempotent(CMD_SPLIT, req.commandKey(), fingerprint, () -> {
445	            BatchRepository.BatchRow parent = repo.findBatchForUpdate(parentKey)
446	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + parentKey));
447	            // 父批行锁后重查命令快照：并发同键请求在锁等待期间可能已由对方提交，
448	            // 此时须重放首次结果而不是因父批已 SPLIT 误判冲突
449	            var logged = loggedResponse(CMD_SPLIT, req.commandKey(), fingerprint);
450	            if (logged.isPresent()) {
451	                return logged.get();
452	            }
453	            assertNoRecalledAncestor(parentKey);
454	            if (!BatchStatus.RELEASED.name().equals(parent.status())) {
455	                throw ApiException.conflict(
456	                        "批次状态 " + parent.status() + " 不允许拆分，仅当前可用的 RELEASED 批次可拆分");
457	            }
458	            for (String childKey : childKeys) {
459	                if (repo.findBatch(childKey).isPresent()) {
460	                    throw ApiException.conflict("子批 batchKey 已存在: " + childKey);
461	                }
462	            }
463	            String now = now();
464	            List<String> required = repo.findRequiredTests(parentKey);
465	            List<SplitResponse.SplitChild> childBodies = new ArrayList<>(children.size());
466	            for (int i = 0; i < children.size(); i++) {
467	                SplitRequest.ChildSpec spec = children.get(i);
468	                repo.insertBatch(new BatchRepository.BatchRow(0L, spec.batchKey(), parent.productCode(),
469	                        spec.batchNo(), parent.producedAt(), BatchStatus.QUARANTINED.name(), now));
470	                for (int j = 0; j < required.size(); j++) {
471	                    repo.insertRequiredTest(spec.batchKey(), required.get(j), j + 1);
472	                }
473	                repo.insertLineage(new BatchRepository.LineageRow(0L, parentKey, spec.batchKey(),
474	                        i + 1, now));
475	                childBodies.add(new SplitResponse.SplitChild(spec.batchKey(), spec.batchNo(),
476	                        parent.productCode(), Instant.parse(parent.producedAt()),
477	                        BatchStatus.QUARANTINED, required, Instant.parse(now)));
478	            }
479	            repo.updateStatus(parentKey, BatchStatus.SPLIT.name());
480	            SplitResponse body = new SplitResponse(parentKey, BatchStatus.SPLIT, childBodies,
481	                    Instant.parse(now));
482	            return new StoredResponse(201, toJson(body));
483	        });
484	    }

