    List<String> childKeys = children.stream().map(SplitRequest.ChildSpec::batchKey).toList();
    if (new HashSet<>(childKeys).size() != childKeys.size()) {
        throw ApiException.conflict("子批 batchKey 在请求内重复");
    }
