    @Test
    void mergeNonReleasedParent_returns409_andRollsBackEverything() throws Exception {
        String released = "BK-MNR-R-" + unique();
        String quarantined = "BK-MNR-Q-" + unique();
        createBatch(released, List.of("t1"), "2026-01-01T00:00:00Z", 201);
