        String newKey = "BK-MNR-N-" + unique();
        merge("CK-MNR-1", newKey, "L1", List.of(released, quarantined), 409);

        // 全部回滚：可用父批状态不变，无新批、无合批边
        assertEquals("RELEASED", currentStatus(released));
